Method.Implementation:

	#dim status as %Status
	set status = $$$OK
	$$$TRACE("Inside IHC.ITF.Operation.CdrDemogrInitiateMerges OnMessage method <"_pRequest.keepMrn_">")

	try {	

		$$$TRACE("Request EMPI# : " _ pRequest.keepMrn)	
		$$$TRACE("Log Dir : " _ ..LogDirectory)		
		set objCdrTuxService = ##class(org.ihc.itf.cdr.CdrMerges).%New(..JavaGateway,..LogDirectory _"/" _$$$JobConfigName _".log", $$$ConfigTrace($$$JobConfigName))
		$$$TRACE("Object name: " _ objCdrTuxService.%ClassName(1))
		do ..objCdrTuxService.CdrMergeCall(pRequest.keepMrn,pRequest.deleteMrn,pRequest.employeeNcid,pRequest.facilityNcid)
	} catch err {	
	        set sysText = ""
 			if (err.%IsA("%Exception.SystemException")){
	 			set sysText = " SystemException: " _err.AsSystemError()_ "; "	 
 			}
 			If $GET(%objlasterror) '=""{
 				set sysText = sysText _ "ErrorText: " _ $System.Status.GetErrorText(%objlasterror) _ "; "	 
 			}
			Set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Out-Cdr-Demogr-INITIATEMERGES",sysText)
	}	    

	 $$$TRACE("OnMessage status: " _ status)	
	 return status
